// Requires: mesh OBJ (File → Open Mesh OBJ)
// Vertex layout: position (float3), normal (float3), UV (float2)

struct VSInput
{
    float3 pos    : POSITION;
    float3 normal : NORMAL;
    float2 uv     : TEXCOORD0;
};

struct VSOutput
{
    float3 worldPos : WORLDPOS;
    float3 normal   : NORMAL;
    float2 uv       : TEXCOORD0;
};

VSOutput VSMain(VSInput input)
{
    VSOutput o;
    o.worldPos = input.pos;
    o.normal = normalize(input.normal);
    o.uv = input.uv;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct VSOutput
{
    float3 worldPos : WORLDPOS;
    float3 normal   : NORMAL;
    float2 uv       : TEXCOORD0;
};

struct HSOutput
{
    float3 worldPos : WORLDPOS;
    float3 normal   : NORMAL;
    float2 uv       : TEXCOORD0;
};

struct HSConstOutput
{
    float edges[3]  : SV_TessFactor;
    float inside    : SV_InsideTessFactor;
    float3 b210 : B210;
    float3 b120 : B120;
    float3 b021 : B021;
    float3 b012 : B012;
    float3 b102 : B102;
    float3 b201 : B201;
    float3 b111 : B111;
};

float3 projectOntoPlane(float3 pt, float3 planePos, float3 planeNormal)
{
    return pt - dot(pt - planePos, planeNormal) * planeNormal;
}

HSConstOutput PatchConstFunc(InputPatch<VSOutput, 3> patch, uint patchID : SV_PrimitiveID)
{
    HSConstOutput o;
    float tess = 6.0;
    o.edges[0] = tess;
    o.edges[1] = tess;
    o.edges[2] = tess;
    o.inside = tess;

    float3 p0 = patch[0].worldPos;
    float3 p1 = patch[1].worldPos;
    float3 p2 = patch[2].worldPos;
    float3 n0 = patch[0].normal;
    float3 n1 = patch[1].normal;
    float3 n2 = patch[2].normal;

    o.b210 = (2.0 * p0 + p1 - dot(p1 - p0, n0) * n0) / 3.0;
    o.b120 = (2.0 * p1 + p0 - dot(p0 - p1, n1) * n1) / 3.0;
    o.b021 = (2.0 * p1 + p2 - dot(p2 - p1, n1) * n1) / 3.0;
    o.b012 = (2.0 * p2 + p1 - dot(p1 - p2, n2) * n2) / 3.0;
    o.b102 = (2.0 * p2 + p0 - dot(p0 - p2, n2) * n2) / 3.0;
    o.b201 = (2.0 * p0 + p2 - dot(p2 - p0, n0) * n0) / 3.0;
    float3 center = (p0 + p1 + p2) / 3.0;
    float3 avg = (o.b210 + o.b120 + o.b021 + o.b012 + o.b102 + o.b201) / 6.0;
    o.b111 = avg + (avg - center) * 0.5;

    return o;
}

[domain("tri")]
[partitioning("fractional_odd")]
[outputtopology("triangle_cw")]
[outputcontrolpoints(3)]
[patchconstantfunc("PatchConstFunc")]
HSOutput HSMain(InputPatch<VSOutput, 3> patch, uint cpID : SV_OutputControlPointID)
{
    HSOutput o;
    o.worldPos = patch[cpID].worldPos;
    o.normal = patch[cpID].normal;
    o.uv = patch[cpID].uv;
    return o;
}

