    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct HSOutput
{
    float3 worldPos : WORLDPOS;
    float3 normal   : NORMAL;
    float2 uv       : TEXCOORD0;
};

struct HSConstOutput
{
    float edges[3]  : SV_TessFactor;
    float inside    : SV_InsideTessFactor;
    float3 b210 : B210;
    float3 b120 : B120;
    float3 b021 : B021;
    float3 b012 : B012;
    float3 b102 : B102;
    float3 b201 : B201;
    float3 b111 : B111;
};

struct DSOutput
{
    float4 pos    : SV_POSITION;
    float3 normal : NORMAL;
    float2 uv     : TEXCOORD0;
};

float4x4 lookAtRH(float3 eye, float3 target, float3 up)
{
    float3 f = normalize(target - eye);
    float3 r = normalize(cross(f, up));
    float3 u = cross(r, f);
    return float4x4(
        r.x, u.x, -f.x, 0,
        r.y, u.y, -f.y, 0,
        r.z, u.z, -f.z, 0,
        -dot(r,eye), -dot(u,eye), dot(f,eye), 1);
}

float4x4 perspectiveRH(float fovY, float aspect, float zn, float zf)
{
    float h = 1.0 / tan(fovY * 0.5);
    float w = h / aspect;
    float a = zf / (zn - zf);
    float b = zn * a;
    return float4x4(
        w, 0, 0, 0,
        0, h, 0, 0,
        0, 0, a, -1,
        0, 0, b, 0);
}

[domain("tri")]
DSOutput DSMain(HSConstOutput patchConst, float3 bary : SV_DomainLocation,
                const OutputPatch<HSOutput, 3> patch)
{
    DSOutput o;

    float u = bary.x;
    float v = bary.y;
    float w = bary.z;

    float3 p0 = patch[0].worldPos;
    float3 p1 = patch[1].worldPos;
    float3 p2 = patch[2].worldPos;

    float3 pos = p0 * u*u*u + p1 * v*v*v + p2 * w*w*w
        + patchConst.b210 * 3.0*u*u*v + patchConst.b120 * 3.0*u*v*v
        + patchConst.b021 * 3.0*v*v*w + patchConst.b012 * 3.0*v*w*w
        + patchConst.b102 * 3.0*w*w*u + patchConst.b201 * 3.0*w*u*u
        + patchConst.b111 * 6.0*u*v*w;

    float3 normal = normalize(u * patch[0].normal + v * patch[1].normal + w * patch[2].normal);
    float2 uv = u * patch[0].uv + v * patch[1].uv + w * patch[2].uv;

    float aspect = resolution_x / resolution_y;
    float angle = drag_accum_x * 0.01;
    float elevation = clamp(-drag_accum_y * 0.01, -1.4, 1.4);
    float dist = max(0.5, 3.0 - scroll_accum_y * 0.3);
    float3 fwd = float3(sin(angle)*cos(elevation), sin(elevation), cos(angle)*cos(elevation));
    float3 right = normalize(cross(float3(0,1,0), fwd));
    float3 camUp = cross(fwd, right);
    float panScale = dist * 0.002;
    float3 panOff = right * (-pan_accum_x * panScale) + camUp * (pan_accum_y * panScale);
    float3 eye = panOff + float3(cos(angle)*cos(elevation)*dist, sin(elevation)*dist, sin(angle)*cos(elevation)*dist);
    float4x4 view = lookAtRH(eye, panOff, float3(0,1,0));
    float4x4 proj = perspectiveRH(1.0, aspect, 0.1, 100.0);

    o.pos = mul(proj, mul(view, float4(pos, 1.0)));
    o.normal = normal;
    o.uv = uv;
    return o;
}

struct DSOutput
{
    float4 pos    : SV_POSITION;
    float3 normal : NORMAL;
    float2 uv     : TEXCOORD0;
};

float4 PSMain(DSOutput input) : SV_Target
{
    float3 n = normalize(input.normal);
    float3 lightDir = normalize(float3(1.0, 1.0, 0.5));
    float diff = saturate(dot(n, lightDir));
    float3 color = float3(0.9, 0.5, 0.2) * (diff * 0.8 + 0.2);
    return float4(color, 1.0);
}
